package com.yuyutian.mytools.media.library.service;
import com.yuyutian.mytools.media.library.model.MediaModels.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.jdbc.core.JdbcTemplate;
import java.time.Instant;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
/** Media Library 领域事务测试。 */ @SpringBootTest class MediaLibraryServiceTest {
 @Autowired private MediaLibraryService service;
 @Autowired private JdbcTemplate jdbc;
 @MockBean private MediaTaskSchedulerClient scheduler;
 @Test void shouldMergeEventCompleteAnalysisAndProtectProgressRevision(){UUID asset=UUID.randomUUID();AssetEvent event=new AssetEvent("event-1",asset,7L,"MEDIA_FILE","42","video.mp4","video/mp4",100,"a".repeat(64),"movies","Movies",null);MediaView media=service.consume(event);assertThat(service.consume(event).id()).isEqualTo(media.id());UUID task=UUID.randomUUID();service.begin(media.id(),new BeginAnalysis("analysis-v1",task,asset));CompleteAnalysis completed=new CompleteAnalysis(task,"summary","description",List.of(new TagInput("Travel",0.9)),List.of(new ArtifactInput(UUID.randomUUID(),"THUMBNAIL","1.0.0")));service.complete(media.id(),completed);service.complete(media.id(),completed);assertThatThrownBy(()->service.complete(media.id(),new CompleteAnalysis(task,"different","description",List.of(),List.of()))).isInstanceOf(IllegalStateException.class);assertThat(service.view(7,media.id()).tags()).containsExactly("travel");ProgressView first=service.progress(7,media.id(),new ProgressRequest(100,1000,false,0,Instant.now()));assertThat(first.revision()).isEqualTo(1);assertThatThrownBy(()->service.progress(7,media.id(),new ProgressRequest(200,1000,false,0,Instant.now()))).isInstanceOf(IllegalStateException.class);}
 @Test void shouldRecordIdempotentAnalysisFailure(){UUID asset=UUID.randomUUID();MediaView media=service.consume(new AssetEvent("failure-event",asset,8L,"MEDIA_FILE","failure","failure.mp4","video/mp4",10,"9".repeat(64),null,null,null));UUID task=UUID.randomUUID();service.begin(media.id(),new BeginAnalysis("analysis-failure",task,asset));FailAnalysis failure=new FailAnalysis(task,"TIMED_OUT","MEDIA_ANALYSIS_TIMEOUT");service.fail(media.id(),failure);service.fail(media.id(),failure);assertThatThrownBy(()->service.complete(media.id(),new CompleteAnalysis(task,null,null,List.of(),List.of()))).isInstanceOf(IllegalStateException.class);}
 @Test void shouldRejectEventIdWithDifferentPayload(){service.consume(new AssetEvent("event-conflict",UUID.randomUUID(),9L,"MEDIA_FILE","1","a.jpg","image/jpeg",5,"b".repeat(64),null,null,null));assertThatThrownBy(()->service.consume(new AssetEvent("event-conflict",UUID.randomUUID(),9L,"MEDIA_FILE","2","b.jpg","image/jpeg",6,"c".repeat(64),null,null,null))).isInstanceOf(IllegalStateException.class);}
 @Test void shouldImportLegacyTagsIdempotentlyAndRejectChangedSnapshotPayload(){UUID asset=UUID.fromString("00000000-0000-4000-8000-000000000010");AssetEvent event=new AssetEvent("legacy-media-event",asset,10L,"LEGACY_ASSET","local_file:10","legacy.mp4","video/mp4",20,"d".repeat(64),null,null,null);LegacyMediaImport request=new LegacyMediaImport("media-v1","snapshot-v1","MyTools","10",event,List.of(new TagInput("Travel",0.8),new TagInput("R18-否",null)));MediaView imported=service.importLegacy(request);assertThat(service.importLegacy(request).id()).isEqualTo(imported.id());assertThat(service.view(10L,imported.id()).tags()).containsExactly("r18-否","travel");LegacyMigrationEvidence evidence=service.legacyMigrationEvidence("media-v1");assertThat(evidence.sourceSnapshotId()).isEqualTo("snapshot-v1");assertThat(evidence.itemCount()).isEqualTo(1);assertThat(evidence.tagCount()).isEqualTo(2);assertThat(evidence.collectionSha256()).isEqualTo("2c1a27dea7829c5e1e1897ec9377ebf441f2a6f8e14b11e0a5ce9444f0067140");assertThatThrownBy(()->service.importLegacy(new LegacyMediaImport("media-v1","snapshot-v1","MyTools","10",event,List.of(new TagInput("Changed",0.5))))).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->service.importLegacy(new LegacyMediaImport("media-v1","snapshot-v1","MyTools","11",new AssetEvent("legacy-duplicate-tags",UUID.randomUUID(),10L,"LEGACY_ASSET","local_file:11","duplicate.mp4","video/mp4",20,"e".repeat(64),null,null,null),List.of(new TagInput("Same",0.5),new TagInput("same",0.7))))).isInstanceOf(IllegalArgumentException.class);}
 @Test void shouldPreserveEachLegacySourceWhenAssetsAreDeduplicated(){UUID asset=UUID.randomUUID();MediaView first=service.importLegacy(new LegacyMediaImport("media-dedup","snapshot-dedup","MyTools","101",new AssetEvent("legacy-source-a",asset,14L,"LEGACY_ASSET","local_file:101","first.mp4","video/mp4",20,"f".repeat(64),null,null,null),List.of(new TagInput("First",0.6))));MediaView second=service.importLegacy(new LegacyMediaImport("media-dedup","snapshot-dedup","MyTools","102",new AssetEvent("legacy-source-b",asset,14L,"LEGACY_ASSET","local_file:102","second.mp4","video/mp4",20,"f".repeat(64),null,null,null),List.of(new TagInput("Second",0.7))));assertThat(second.id()).isEqualTo(first.id());assertThat(service.view(14L,first.id()).tags()).containsExactly("first","second");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM media_item_source WHERE media_item_id=?",Integer.class,first.id().toString())).isEqualTo(2);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM media_item_source_tag WHERE media_item_id=?",Integer.class,first.id().toString())).isEqualTo(2);assertThat(service.legacyMigrationEvidence("media-dedup").itemCount()).isEqualTo(2);ReconciliationPage reconciliation=service.reconciliation(null,200);assertThat(reconciliation.sourceRelationCount()).isGreaterThanOrEqualTo(2);assertThat(reconciliation.sourceTagRelationCount()).isGreaterThanOrEqualTo(2);}
 @Test void shouldResolveMigratedLegacyAnalysisTarget(){UUID asset=UUID.randomUUID();MediaView media=service.importLegacy(new LegacyMediaImport("media-analysis","snapshot-analysis","MyTools","501",new AssetEvent("legacy-analysis-target",asset,15L,"LEGACY_ASSET","local_file:501","target.mp4","video/mp4",30,"7".repeat(64),null,null,null),List.of()));LegacyAnalysisTarget target=service.legacyAnalysisTarget(501);assertThat(target.mediaItemId()).isEqualTo(media.id());assertThat(target.assetRegistryId()).isEqualTo(asset);assertThat(target.ownerId()).isEqualTo(15L);assertThat(target.contentSha256()).isEqualTo("7".repeat(64));assertThatThrownBy(()->service.legacyAnalysisTarget(999999)).isInstanceOf(IllegalArgumentException.class);}
 @Test void shouldPublishOnlyFullyImportedScan(){BeginScan request=new BeginScan(11L,"scan-key","movies","Movies","d".repeat(64),1);ScanView scan=service.beginScan(request);ScanEntry entry=new ScanEntry("scan:"+"1".repeat(64),"a.mp4","video/mp4",10,"e".repeat(64));service.stageScan(scan.id(),new StageScanEntries(List.of(entry)));assertThatThrownBy(()->service.finishScan(scan.id(),new FinishScan("f".repeat(64)))).isInstanceOf(IllegalStateException.class);MediaView imported=service.consume(new AssetEvent("scan-event",UUID.randomUUID(),11L,"MEDIA_SCAN",entry.sourceBusinessId(),entry.displayName(),entry.mimeType(),entry.sizeBytes(),entry.contentSha256(),"movies","Movies",scan.id()));ScanView completed=service.finishScan(scan.id(),new FinishScan("f".repeat(64)));assertThat(completed.status()).isEqualTo("COMPLETED");assertThat(completed.importedCount()).isEqualTo(1);assertThat(service.finishScan(scan.id(),new FinishScan("f".repeat(64))).status()).isEqualTo("COMPLETED");ScanView empty=service.beginScan(new BeginScan(11L,"scan-empty","movies","Movies","d".repeat(64),0));service.stageScan(empty.id(),new StageScanEntries(List.of()));service.finishScan(empty.id(),new FinishScan("0".repeat(64)));assertThat(service.view(11,imported.id()).status()).isEqualTo("MISSING");}
 @Test void shouldKeepDeduplicatedMediaReadyWhileAnotherDirectoryContainsIt(){UUID asset=UUID.randomUUID();ScanView first=service.beginScan(new BeginScan(12L,"multi-a","a","A","a".repeat(64),1));ScanEntry a=new ScanEntry("scan:"+"a".repeat(64),"a.mp4","video/mp4",10,"1".repeat(64));service.stageScan(first.id(),new StageScanEntries(List.of(a)));MediaView media=service.consume(new AssetEvent("multi-event-a",asset,12L,"MEDIA_SCAN",a.sourceBusinessId(),a.displayName(),a.mimeType(),a.sizeBytes(),a.contentSha256(),"a","A",first.id()));service.finishScan(first.id(),new FinishScan("1".repeat(64)));ScanView second=service.beginScan(new BeginScan(12L,"multi-b","b","B","b".repeat(64),1));ScanEntry b=new ScanEntry("scan:"+"b".repeat(64),"b.mp4","video/mp4",10,"1".repeat(64));service.stageScan(second.id(),new StageScanEntries(List.of(b)));service.consume(new AssetEvent("multi-event-b",asset,12L,"MEDIA_SCAN",b.sourceBusinessId(),b.displayName(),b.mimeType(),b.sizeBytes(),b.contentSha256(),"b","B",second.id()));service.finishScan(second.id(),new FinishScan("2".repeat(64)));ScanView emptyA=service.beginScan(new BeginScan(12L,"multi-a-empty","a","A","a".repeat(64),0));service.stageScan(emptyA.id(),new StageScanEntries(List.of()));service.finishScan(emptyA.id(),new FinishScan("3".repeat(64)));assertThat(service.view(12,media.id()).status()).isEqualTo("READY");ScanView emptyB=service.beginScan(new BeginScan(12L,"multi-b-empty","b","B","b".repeat(64),0));service.stageScan(emptyB.id(),new StageScanEntries(List.of()));service.finishScan(emptyB.id(),new FinishScan("4".repeat(64)));assertThat(service.view(12,media.id()).status()).isEqualTo("MISSING");}
 @Test void shouldAdvanceRevisionAndProduceDeterministicReconciliationPages(){UUID asset=UUID.randomUUID();MediaView media=service.consume(new AssetEvent("reconcile-event",asset,13L,"MEDIA_FILE","reconcile","r.mp4","video/mp4",10,"8".repeat(64),null,null,null));ReconciliationPage before=service.reconciliation(null,200);assertThat(before.libraryRevision()).isPositive();assertThat(before.pageDigestSha256()).hasSize(64);service.progress(13,media.id(),new ProgressRequest(1,10,false,0,Instant.now()));ReconciliationPage after=service.reconciliation(null,200);assertThat(after.libraryRevision()).isGreaterThan(before.libraryRevision());assertThat(after.pageDigestSha256()).isNotEqualTo(before.pageDigestSha256());assertThatThrownBy(()->service.reconciliation(null,201)).isInstanceOf(IllegalArgumentException.class);}
 @Test void shouldPageOwnerMediaWithoutLeakingOtherOwners(){MediaView first=service.consume(new AssetEvent("list-a",UUID.randomUUID(),21L,"MEDIA_FILE","list-a","a.mp4","video/mp4",10,"1".repeat(64),null,null,null));service.consume(new AssetEvent("list-b",UUID.randomUUID(),22L,"MEDIA_FILE","list-b","b.mp4","video/mp4",10,"2".repeat(64),null,null,null));MediaPage page=service.list(21L,null,false,null,100);assertThat(page.items()).extracting(MediaView::id).containsExactly(first.id());assertThatThrownBy(()->service.list(21L,null,false,null,101)).isInstanceOf(IllegalArgumentException.class);}
 @Test void shouldQueryCatalogDirectlyWithoutSchedulingTasks(){service.importLegacy(new LegacyMediaImport("catalog-a","catalog-snapshot","MyTools","701",new AssetEvent("catalog-event-a",UUID.randomUUID(),61L,"LEGACY_ASSET","local_file:701","mountain.jpg","image/jpeg",20,"a".repeat(64),null,null,null),List.of(new TagInput("Nature",0.9))));service.importLegacy(new LegacyMediaImport("catalog-b","catalog-snapshot","MyTools","702",new AssetEvent("catalog-event-b",UUID.randomUUID(),61L,"LEGACY_ASSET","local_file:702","city.jpg","image/jpeg",20,"b".repeat(64),null,null,null),List.of(new TagInput("City",0.8))));MediaCatalogPage page=service.catalog(61L,"image/","nature","mountain",1,100,false);assertThat(page.total()).isEqualTo(1);assertThat(page.items()).extracting(MediaView::displayName).containsExactly("mountain.jpg");assertThat(page.tags()).extracting(MediaTagCount::name).contains("nature");verifyNoInteractions(scheduler);}
 @Test void shouldDeleteOnlyOwnerMediaAndKeepDeletionIdempotent(){MediaView media=service.consume(new AssetEvent("delete-a",UUID.randomUUID(),23L,"MEDIA_FILE","delete-a","book.epub","application/epub+zip",10,"3".repeat(64),null,null,null));assertThatThrownBy(()->service.delete(24L,media.id())).isInstanceOf(IllegalArgumentException.class);service.delete(23L,media.id());service.delete(23L,media.id());assertThat(service.list(23L,null,false,null,100).items()).extracting(MediaView::id).doesNotContain(media.id());assertThat(service.list(23L,null,true,null,100).items()).extracting(MediaView::id).contains(media.id());assertThat(service.view(23L,media.id()).status()).isEqualTo("MISSING");}
 @Test void shouldCreateQueryAndCancelOwnerBoundDirectoryScan(){UUID taskId=UUID.randomUUID();when(scheduler.createScan(any(),eq(31L),startsWith("media-scan:"),anyMap())).thenReturn(taskId);when(scheduler.status(taskId)).thenReturn("RUNNING","RUNNING","CANCELLING");StartDirectoryScan request=new StartDirectoryScan("scan-request-1","/media/movies","movies","Movies",true,"analysis-v1");OperationView created=service.startDirectoryScan(31L,request);OperationView replayed=service.startDirectoryScan(31L,request);assertThat(replayed.id()).isEqualTo(created.id());assertThatThrownBy(()->service.startDirectoryScan(31L,new StartDirectoryScan("scan-request-1","/media/other","movies","Movies",true,"analysis-v1"))).isInstanceOf(IllegalStateException.class);assertThat(service.cancelOperation(created.id(),31L).status()).isEqualTo("CANCELLING");assertThatThrownBy(()->service.operation(created.id(),32L)).isInstanceOf(IllegalArgumentException.class);verify(scheduler,times(1)).createScan(any(),eq(31L),startsWith("media-scan:"),argThat(parameters->parameters.get("rootPath").equals("/media/movies")&&parameters.get("ownerId").equals(31L)));verify(scheduler).cancel(taskId);}
 @Test void shouldCreateStorageBackedAnalysisOperation(){UUID asset=UUID.randomUUID();MediaView media=service.consume(new AssetEvent("analysis-operation",asset,41L,"MEDIA_FILE","analysis-operation","video.mp4","video/mp4",123,"a".repeat(64),null,null,null));UUID taskId=UUID.randomUUID();when(scheduler.createAnalysis(any(),startsWith("media-analysis:"),anyMap())).thenReturn(taskId);when(scheduler.status(taskId)).thenReturn("PENDING","RUNNING");StartAnalysis request=new StartAnalysis("analysis-request-1","analysis-v2",8,2.5);OperationView created=service.startAnalysis(media.id(),41L,request);OperationView replayed=service.startAnalysis(media.id(),41L,request);assertThat(created.operationType()).isEqualTo("ANALYSIS");assertThat(replayed.id()).isEqualTo(created.id());verify(scheduler,times(1)).createAnalysis(any(),startsWith("media-analysis:41:"),argThat(parameters->parameters.get("assetRegistryId").equals(asset.toString())&&!parameters.containsKey("sourcePath")&&parameters.get("frameCount").equals(8)));assertThatThrownBy(()->service.startAnalysis(media.id(),42L,request)).isInstanceOf(IllegalArgumentException.class);}
}
